package com.myaaptha.domain.health;import java.security.Principal;import org.springframework.http.ResponseEntity;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/health") public class HealthController{private final HealthService service;public HealthController(HealthService s){service=s;}@GetMapping("/dashboard")public HealthService.Dashboard dashboard(Principal p){return service.dashboard(id(p));}@PostMapping("/reports")public HealthService.Report add(Principal p,@RequestBody HealthService.ReportInput input){return service.add(id(p),input);}@DeleteMapping("/reports/{id}")public ResponseEntity<Void>delete(Principal p,@PathVariable Long id){service.delete(id(p),id);return ResponseEntity.noContent().build();}private Long id(Principal p){return Long.valueOf(p.getName());}}
